u=DraftUnit('U05','家庭：認識小鎮的新朋友');p=u.pack;q=u.question
words=[('ちち','自己的父親'),('はは','自己的母親'),('あに','自己的哥哥'),('あね','自己的姊姊'),('おとうと','弟弟'),('いもうと','妹妹'),('そふ','自己的祖父／外祖父'),('そぼ','自己的祖母／外祖母'),('おとうさん','別人的父親；也可用來叫爸爸'),('おかあさん','別人的母親；也可用來叫媽媽'),('おにいさん','別人的哥哥；也可用來叫哥哥'),('おねえさん','別人的姊姊；也可用來叫姊姊'),('おじいさん','別人的祖父；也可稱呼老爺爺'),('おばあさん','別人的祖母；也可稱呼老奶奶'),('かぞく','家人／家庭'),('きょうだい','兄弟姊妹的合稱'),('おとこのこ','男孩'),('おんなのこ','女孩'),('こども','孩子'),('おとな','大人'),('おじ','自己的叔伯舅等男性長輩'),('おば','自己的姑姨等女性長輩'),('いとこ','堂兄弟姊妹／表兄弟姊妹'),('りょうしん','雙親'),('なんにん','幾個人')]
p['vocabulary']=[dict(id=f'U05-V{i:02}',text=t,reading=t,meaning=m) for i,(t,m) in enumerate(words,1)]
p['kanji']=[dict(id=f'U05-K{i:02}',text=t,reading=r,meaning=m) for i,(t,r,m) in enumerate([('父','ちち','自己的父親'),('母','はは','自己的母親'),('兄','あに','自己的哥哥'),('姉','あね','自己的姊姊'),('子','こ','孩子；こども常寫成子ども')],1)]
p['grammar']=[dict(id=g,title=t,prerequisites=['K-HIRA',dep]) for g,t,dep in [('G13','人＋と：列出人物','G12'),('G14','人数：一人・二人・N人','G13'),('G15','Nがいます：介紹家人','G14')]]
for n,(start,end,title,titleja) in enumerate([(0,5,'介紹自己的家人','じぶんのかぞく'),(5,10,'祖父母與稱呼','そふ・そぼとよびかた'),(10,15,'禮貌稱呼與家人','かぞくのことば'),(15,20,'兄弟姊妹與大人小孩','きょうだい・こども・おとな'),(20,25,'親戚與人數','しんせきとにんずう')],1):
 vs=p['vocabulary'][start:end];body='\n'.join(f"{v['text']}：{v['meaning']}" for v in vs)
 if n==1:body+='\n對外介紹自己的爸爸用ちち，媽媽用はは。弟弟與妹妹沒有あに／あね的年長意思。'
 if n==2:body+='\n叫爸爸可以說おとうさん；對朋友談自己的爸爸用ちち。不同情境的用法要分開。'
 if n==3:body+='\n外觀無法證明誰和誰是一家人。稱呼依故事的介紹，不能看衣服猜關係。每個家庭的組成都可能不同。'
 if n==4:body+='\nきょうだい可以包括姊妹，不只男生。子ども讀こども；這裡的子讀こ。'
 if n==5:body+='\nなんにん詢問人數，不是名字。這課只介紹虛構居民；不必寫自己的家人或透露私人資料。'
 id=u.teach(f'words-{n}',title,titleja,body,'ことばをきいて、よびかたをたしかめよう。',vs[0]['text'],vs[0]['meaning'],['V-CONTEXT','V-PARA','K-HIRA','K-KATA'],'。'.join(v['reading'] for v in vs)+'。',vocabularyIds=[v['id'] for v in vs]);u.wordcards.append(id)
u.teach('kanji','把家人的稱呼讀出來','かぞくのかんじ','父＝ちち、母＝はは、兄＝あに、姉＝あね、子＝こ。\n子ども＝こども。\n這課先讀對外介紹自己家人的稱呼。父在お父さん裡讀とう，不是把所有父都讀ちち。','父はちち、母ははは、兄はあに、姉はあね。子どもの子は、こです。','父（ちち）と 母（はは）','自己的爸爸和媽媽。',['K-SCRIPT'],'ちち。はは。あに。あね。こ。こども。',kanjiIds=[k['id'] for k in p['kanji']],prerequisites=u.wordcards)
u.teach('G13','把人物連起來','ひととひとをつなぐ','列出兩個人用AとB：あにとあね＝哥哥和姊姊。\n三個人可說AとBとC；也可用頓號列出，最後用と。\n正例：ちちと ははが います。兩人都在。\n反例：ちちの はは表示爸爸的媽媽，不是爸爸和媽媽。の表示關係，と列出成員。\nと在這裡表示「和」，不表示年齡或人數。','あにとあね。ちちとはは。とで、ひとをならべます。','あにと あねと わたし','哥哥、姊姊和我。',['G13'],'あにとあね。ちちとははがいます。あにとあねとわたし。ちちのははは、そぼです。',grammarIds=['G13'],prerequisites=['U05-teach-kanji'])
u.teach('G14','人數有兩個特別讀音','ひとり・ふたり','一人＝ひとり、二人＝ふたり；不是いちにん／ににん。\n三人＝さんにん、四人＝よにん、五人＝ごにん、六人＝ろくにん。四人不是よんにん。\n人（にん）用來數人，不把貓狗算進人數。\n質問：なんにんですか。回答：三人です。\n家族は四人です計算的是故事中全部家人；如果名單含說話者，要把わたし也算進去。','ひとり、ふたり、さんにん、よにん、ごにん、ろくにん。ひとをかぞえます。','ちちと ははと わたし。三人（さんにん）です。','爸爸、媽媽和我，共三人。',['G14'],'ひとり。ふたり。さんにん。よにん。ごにん。ろくにん。なんにんですか。さんにんです。',grammarIds=['G14'],prerequisites=['U05-teach-G13'])
u.teach('G15','介紹故事裡的家人','かぞくをしょうかいする','「あねが います」表示有姊姊。家人是人，用います。\n「あねが 一人 います」表示有一位姊姊；人數放在が之後、います之前。\n沒有弟弟可說「おとうとは いません」。\n問「きょうだいが いますか」是在問有沒有兄弟姊妹；回答有時可再介紹「あにが います」。\n不要用あります介紹人，也不要把「あねがいます」解讀為自己的名字叫あね。','あねがひとりいます。おとうとはいません。かぞくは、ひとです。いますをつかいます。','いもうとが 二人（ふたり）います。','有兩個妹妹。',['G15'],'あねがひとりいます。いもうとがふたりいます。おとうとはいません。きょうだいがいますか。はい、あにがいます。',grammarIds=['G15'],prerequisites=['U05-teach-G14'])
u.teach('story','只用故事的線索介紹','おはなしのひとをしょうかいしよう','先看說話者是誰，再讀家人名單與人數。\n表格把名字、稱呼、數量放在不同欄；不要把名單之外的人加進去。\n聽「だれ」找人物，聽「なんにん」找人數；聽到否定いません，要排除那位家人。\n聽力任務的輔助用語：もっています＝拿著；さがしてください＝請找出；も＝也。看到あかい／あおい，回想前課的紅色／藍色。\n插畫只用來數看得到的人；不能憑年齡、性別或服裝認定親屬關係。\n每種家庭都值得尊重；本課只問虛構角色。','だれのおはなしか、なんにんいるかをたしかめます。えでは、みえるひとだけをかぞえましょう。','アキ：そぼと わたし。二人です。','小秋說：奶奶和我，兩個人。',['R-SHORT','R-MID','R-INFO','L-TASK','L-KEY','L-EXPR','L-RESP','G-ORDER','G-TEXT'],'だれですか。そぼです。なんにんですか。ふたりです。そぼとわたしです。',prerequisites=['U05-teach-G15'])
readings=[('わたしは ハルです。あねが 一人 います。あねは がくせいです。おとうとは いません。','R-SHORT'),('ミオです。かぞくは 三人です。ははと そぼと わたしです。そぼは いま にわに います。ははは へやに います。わたしも へやに います。にわには ねこも います。ねこは 人のかずには いれません。','R-MID'),('小鎮居民介紹表\nハル｜あね 一人｜おとうと いません\nユイ｜あに 一人・いもうと 一人\nソラ｜きょうだい いません\nアキ｜おとうと 二人','R-INFO'),('ユイ：きょうだいが いますか。\nアキ：はい、おとうとが 二人 います。\nユイ：おにいさんは いますか。\nアキ：いいえ、あには いません。おとうとは がくせいです。わたしも がくせいです。','R-MID')]
p['readings']=[dict(id=f'U05-R{i:02}',text=t,skillId=skill) for i,(t,skill) in enumerate(readings,1)]
