p['listening']=[dict(id=f'U05-L{i:02}',script=t,audioSrc=f'/assets/audio/u05/listening-{i:02}.wav',skillId=skill,reviewStatus='DRAFT') for i,(t,skill) in enumerate(clips,1)]
